ORDER = ("groups", "calendars")


def provider(collection, cursor):
    if collection == "groups" and cursor is None:
        return ["g1"], "page2"
    if collection == "groups":
        return ["g2"], None
    return ["c1"], None


def coalesce_alpha(rows):
    return rows


def worker_alpha():
    result = []
    for collection in ORDER:
        cursor = None
        while True:
            rows, following = provider(collection, cursor)
            result.extend(coalesce_alpha(rows))
            if following is None:
                break
            cursor = following
    return result


def engine_select(state):
    if state["phase"] == len(ORDER):
        return None
    return ORDER[state["phase"]], state["cursor"]


def engine_observe(state, rows, following):
    state["rows"].extend(rows)
    if following is None:
        state["phase"] += 1
    state["cursor"] = following


def worker_beta():
    state = {"phase": 0, "cursor": None, "rows": []}
    while (request := engine_select(state)) is not None:
        rows, following = provider(*request)
        engine_observe(state, rows, following)
    return state["rows"]

from urllib.parse import urlsplit


def initial_url():
    return "https://graph.microsoft.com/v1.0/users/u1/mailFolders/f1/messages/delta"


def alpha(url):
    parsed = urlsplit(url)
    return (parsed.scheme == "https" and parsed.netloc == "graph.microsoft.com"
            and parsed.path == urlsplit(initial_url()).path)


def beta(url):
    parsed = urlsplit(url)
    paths = {"/v1.0/users/u1/mailFolders/f1/messages/delta",
             "/v1.0/users/u1/mailFolders('f1')/messages/delta"}
    return (parsed.scheme == "https" and parsed.netloc == "graph.microsoft.com"
            and parsed.path in paths)

